1	// Fringe Planner — page logic.
2	//
3	// Self-contained ES module: no globals shared with the home site's js/app.js.
4	// Wires the real computation engine (./lib/engine.js, ./lib/favourites.js —
5	// pure, untouched here) to the two-screen UI described in
6	// plan/design/mock.html + plan/design/DESIGN_NOTES.md.
7	//
8	// Screen 1 (input): drag/drop or pick a favourites CSV, or load the bundled
9	//   sample. Screen 2 (calendar): one lane per matched favourite across
10	//   August 2026, with a draggable date window and a start-time range slider
11	//   that filter live via engine.summarize().
12	
13	import { parseFavourites, urlFromSlug } from "./lib/favourites.js";
14	import { buildIndex, matchFavourites, summarize } from "./lib/engine.js";
15	
16	// ES modules are always strict mode, so no "use strict" directive is needed.
17	
18	// --- Constants --------------------------------------------------------
19	
20	const DATA_URL = "../data/normalized/shows.json";
21	const SAMPLE_URL = "./sample-favourites.csv";
22	
23	const YEAR = 2026;
24	const MONTH = "08"; // August, 2-digit
25	const DAYS_IN_MONTH = 31; // Aug 1–31 is the axis this calendar draws.
26	// TODO: the underlying data actually spans 2026-07-24 through 2026-08-31
27	// (previews before Aug 1, and a handful of performances after Aug 31 do not
28	// occur — the latest date in the dataset is Aug 31 itself). Performances
29	// outside the Aug 1–31 axis simply fall off the calendar; this is expected
30	// per the spec and rare in practice (previews are the main case).
31	const FEST_END_DAY = 25; // Core run ends Mon 25 Aug; 26–31 draws as a shaded "after" zone.
32	
33	const T_MIN = 480; // 08:00 in minutes-since-midnight — low enough to include the
34	// morning shows (~230 in the catalogue start 08:00–09:59); a 10:00 floor would
35	// silently make an early favourite uncountable. Residual: the ~4 catalogue
36	// shows starting before 08:00 (midnight/early exhibitions) still fall off; a
37	// data-driven floor (earliest matched favourite) is the documented next step.
38	const T_MAX = 1440; // 24:00
39	const T_STEP = 30; // 30-minute snap
40	const T_GAP = 60; // minimum 1h span between the two time handles
41	
42	const DEFAULT_D0 = 7; // default date window: Aug 7 → Aug 24 (the festival trip window)
43	const DEFAULT_D1 = 24;
44	
45	// --- Small helpers ------------------------------------------------------
46	
47	const $ = (id) => document.getElementById(id);
48	const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
49	const pad2 = (n) => String(n).padStart(2, "0");
50	
51	/** "YYYY-MM-DD" for a day-of-month within August 2026. */
52	function dateStr(day) {
53	  return `${YEAR}-${MONTH}-${pad2(day)}`;
54	}
55	
56	/** Minutes-since-midnight -> "HH:MM", with 1440 rendering as "24:00". */
57	function fmtT(mins) {
58	  return `${pad2(Math.floor(mins / 60))}:${pad2(mins % 60)}`;
59	}
60	
61	// 1 Aug 2026 is a Saturday; compute weekday letters from real dates rather
62	// than hardcoding, so this stays correct if the festival year ever changes.
63	const DOW_SHORT = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
64	function dowShort(day) {
65	  return DOW_SHORT[new Date(Date.UTC(YEAR, 7, day)).getUTCDay()];
66	}
67	function isWeekend(day) {
68	  const d = new Date(Date.UTC(YEAR, 7, day)).getUTCDay();
69	  return d === 0 || d === 6;
70	}
71	
72	// --- App state ------------------------------------------------------------
73	
74	const state = {
75	  index: null, // Map<slug, show> — the full catalogue
76	  matched: [], // full show objects for the user's matched favourites
77	  totalFavourites: 0,
78	  missingSlugs: [],
79	  filename: "",
80	  // Date/time window (drives summarize()'s filter):
81	  d0: DEFAULT_D0,
82	  d1: DEFAULT_D1,
83	  t0: T_MIN,
84	  t1: T_MAX,
85	  // Populated once per upload by buildCalendar():
86	  laneRefs: [], // [{ slug, el, statusEl }] in display (sorted) order
87	  layout: { trackLeft: 0, trackWidth: 0, dayW: 0 },
88	  dayHeaderBuilt: false,
89	};
90	
91	// --- Data loading -----------------------------------------------------
92	
93	async function loadData() {
94	  $("loadingState").hidden = false;
95	  $("errorState").hidden = true;
96	  $("screen1").hidden = true;
97	  try {
98	    const res = await fetch(DATA_URL);
99	    if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${DATA_URL}`);
100	    const shows = await res.json();
101	    state.index = buildIndex(shows);
102	    $("loadingState").hidden = true;
103	    $("screen1").hidden = false;
104	  } catch (err) {
105	    console.error("Fringe Planner: failed to load show data", err);
106	    $("loadingState").hidden = true;
107	    $("errorDetail").textContent =
108	      "Check your connection and try again. (" + (err && err.message ? err.message : "unknown error") + ")";
109	    $("errorState").hidden = false;
110	  }
111	}
112	
113	// --- Screen 1: favourites intake -----------------------------------------
114	
115	/** Read a File via FileReader and hand its text to processFavouritesText. */
116	function handleFile(file) {
117	  if (!file) return;
118	  const reader = new FileReader();
119	  reader.onload = () => processFavouritesText(String(reader.result || ""), file.name);
120	  reader.onerror = () => {
121	    console.error("Fringe Planner: failed to read file", reader.error);
122	    alert("Couldn't read that file — please try again.");
123	  };
124	  reader.readAsText(file);
125	}
126	
127	/** Parse favourites text, match against the catalogue, and render the result. */
128	function processFavouritesText(text, filename) {
129	  const slugs = parseFavourites(text);
130	  const { matched, missingSlugs } = matchFavourites(slugs, state.index);
131	
132	  state.totalFavourites = slugs.length;
133	  state.matched = matched;
134	  state.missingSlugs = missingSlugs;
135	  state.filename = filename;
136	
137	  renderUploadSummary();
138	
139	  if (matched.length > 0) {
140	    // Reset the window to the defaults on every fresh upload.
141	    state.d0 = DEFAULT_D0;
142	    state.d1 = DEFAULT_D1;
143	    state.t0 = T_MIN;
144	    state.t1 = T_MAX;
145	    buildCalendar();
146	    revealCalendar();
147	  } else {
148	    $("screen2").hidden = true;
149	  }
150	}
151	
152	function renderUploadSummary() {
153	  const { totalFavourites, matched, missingSlugs, filename } = state;
154	
155	  $("summaryCap").hidden = false;
156	  const summaryEl = $("uploadSummary");
157	  summaryEl.hidden = false;
158	  summaryEl.classList.toggle("is-partial", missingSlugs.length > 0);
159	
160	  $("usMain").textContent =
161	    totalFavourites === 0
162	      ? "No favourites found in that file"
163	      : `${totalFavourites} favourite${totalFavourites === 1 ? "" : "s"} loaded`;
164	
165	  if (totalFavourites === 0) {
166	    $("usSub").textContent = "We couldn't find any edfringe.com show links in that file.";
167	  } else {
168	    let sub = `${matched.length} matched to our show data`;
169	    if (missingSlugs.length > 0) {
170	      sub += ` · ${missingSlugs.length} we couldn't find `;
171	    }
172	    $("usSub").textContent = sub;
173	    if (missingSlugs.length > 0) {
174	      const whichBtn = document.createElement("button");
175	      whichBtn.type = "button";
176	      whichBtn.className = "link-quiet";
177	      whichBtn.textContent = "(which?)";
178	      whichBtn.addEventListener("click", toggleMissingList);
179	      $("usSub").appendChild(whichBtn);
180	    }
181	  }
182	  $("usFile").textContent = filename;
183	
184	  renderMissingList();
185	
186	  const continueRow = $("continueRow");
187	  continueRow.hidden = matched.length === 0;
188	  $("continueBtn").disabled = matched.length === 0;
189	}
190	
191	function renderMissingList() {
192	  const list = $("missingList");
193	  list.innerHTML = "";
194	  list.hidden = true;
195	  for (const slug of state.missingSlugs) {
196	    const li = document.createElement("li");
197	    const a = document.createElement("a");
198	    a.href = urlFromSlug(slug);
199	    a.target = "_blank";
200	    a.rel = "noopener";
201	    a.className = "link-quiet";
202	    a.innerHTML = `<code>${slug}</code>`;
203	    li.appendChild(a);
204	    list.appendChild(li);
205	  }
206	}
207	
208	function toggleMissingList() {
209	  const list = $("missingList");
210	  list.hidden = !list.hidden;
211	}
212	
213	function revealCalendar() {
214	  const screen2 = $("screen2");
215	  screen2.hidden = false;
216	  // Layout needs real geometry, which only exists once the panel is visible.
217	  requestAnimationFrame(() => layoutOverlay());
218	  screen2.scrollIntoView({ behavior: "smooth", block: "start" });
219	}
220	
221	// --- Screen 2: calendar ----------------------------------------------------
222	
223	/** Current summarize() filter derived from state.{d0,d1,t0,t1}. */
224	function currentFilter() {
225	  return {
226	    dateStart: dateStr(state.d0),
227	    dateEnd: dateStr(state.d1),
228	    startTimeMin: state.t0,
229	    startTimeMax: state.t1,
230	  };
231	}
232	
233	/** Mode of a show's performance start times — used to order lanes morning → night. */
234	function typicalStartTime(performances) {
235	  const counts = new Map();
236	  for (const p of performances) counts.set(p.start, (counts.get(p.start) || 0) + 1);
237	  let best = null;
238	  let bestCount = -1;
239	  for (const [time, count] of counts) {
240	    if (count > bestCount || (count === bestCount && (best === null || time < best))) {
241	      best = time;
242	      bestCount = count;
243	    }
244	  }
245	  return best || "00:00";
246	}
247	
248	/** Build the static day-of-month header row (runs once; independent of data). */
249	function ensureDayHeader() {
250	  if (state.dayHeaderBuilt) return;
251	  const dayHead = $("dayHead");
252	  dayHead.innerHTML = "";
253	  for (let d = 1; d <= DAYS_IN_MONTH; d++) {
254	    const col = document.createElement("div");
255	    col.className = "day-col" + (isWeekend(d) ? " wknd" : "") + (d > FEST_END_DAY ? " post" : "");
256	    col.innerHTML = `<span class="day-dow">${dowShort(d)}</span><span class="day-num">${d}</span>`;
257	    dayHead.appendChild(col);
258	  }
259	  state.dayHeaderBuilt = true;
260	}
261	
262	/**
263	 * (Re)build the lanes from scratch: one row per matched favourite, sorted by
264	 * typical start time. Performance marks (filled/hollow/absent) are drawn from
265	 * `available`/`soldOut`, which don't depend on the date/time filter, so this
266	 * only needs to run once per upload — dragging the window only changes
267	 * per-lane verdicts (see applyVerdicts), not the marks themselves.
268	 */
269	function buildCalendar() {
270	  ensureDayHeader();
271	
272	  const filter = currentFilter();
273	  const result = summarize(state.matched, filter, state.totalFavourites);
274	  const bySlug = new Map(result.shows.map((s) => [s.slug, s]));
275	  const metaBySlug = new Map(state.matched.map((s) => [s.slug, s]));
276	
277	  const ordered = [...result.shows].sort(
278	    (a, b) => typicalStartTime(a.performances).localeCompare(typicalStartTime(b.performances))
279	  );
280	
281	  const lanesEl = $("lanes");
282	  lanesEl.innerHTML = "";
283	  state.laneRefs = [];
284	
285	  for (const show of ordered) {
286	    const meta = metaBySlug.get(show.slug) || {};
287	    const start = typicalStartTime(show.performances);
288	
289	    const lane = document.createElement("div");
290	    lane.className = "cal-row lane";
291	    lane.dataset.slug = show.slug;
292	
293	    const label = document.createElement("div");
294	    label.className = "lane-label";
295	    label.title = `${show.title} — ${start} · ${meta.genre || ""} · ${meta.venueName || ""}`;
296	    label.innerHTML =
297	      `<div class="lane-title">${escapeHtml(show.title)}</div>` +
298	      `<div class="lane-meta"><span class="lm-time">${start}</span> · ${escapeHtml(meta.genre || "")} · ${escapeHtml(meta.venueName || "")}</div>`;
299	
300	    const track = document.createElement("div");
301	    track.className = "lane-track";
302	    track.appendChild(buildDayCells(show.performances));
303	
304	    const statusEl = document.createElement("div");
305	    statusEl.className = "lane-status";
306	
307	    lane.appendChild(label);
308	    lane.appendChild(track);
309	    lane.appendChild(statusEl);
310	    lanesEl.appendChild(lane);
311	
312	    state.laneRefs.push({ slug: show.slug, el: lane, statusEl });
313	  }
314	
315	  applyVerdicts(bySlug, filter);
316	  updateHero(result.counts, filter);
317	  layoutOverlay();
318	}
319	
320	/** Build the 31 day cells (filled/hollow/absent) for one show's performances. */
321	function buildDayCells(performances) {
322	  const byDay = new Map(); // day-of-month -> performances that land on it
323	  for (const p of performances) {
324	    if (!p.date.startsWith(`${YEAR}-${MONTH}-`)) continue; // outside the Aug axis — see TODO above
325	    const day = Number(p.date.slice(8, 10));
326	    if (day < 1 || day > DAYS_IN_MONTH) continue;
327	    if (!byDay.has(day)) byDay.set(day, []);
328	    byDay.get(day).push(p);
329	  }
330	
331	  const frag = document.createDocumentFragment();
332	  for (let d = 1; d <= DAYS_IN_MONTH; d++) {
333	    const cell = document.createElement("span");
334	    cell.style.gridColumn = String(d);
335	    const entries = byDay.get(d);
336	    if (entries && entries.length > 0) {
337	      const anyAvailable = entries.some((p) => p.available);
338	      cell.className = "cell " + (anyAvailable ? "cell-av" : "cell-sold");
339	      cell.title = entries
340	        .map((p) => `${dowShort(d)} ${d} Aug · ${p.start} · ${p.available ? "tickets available" : "sold out"}`)
341	        .join("; ");
342	    }
343	    frag.appendChild(cell);
344	  }
345	  return frag;
346	}
347	
348	/** Escape untrusted show text before inserting via innerHTML. */
349	function escapeHtml(s) {
350	  return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
351	}
352	
353	/**
354	 * Update each lane's dimmed/active state and right-hand verdict from a fresh
355	 * summarize() result — this is the cheap per-drag update (no DOM rebuild).
356	 */
357	function applyVerdicts(bySlug, filter) {
358	  for (const ref of state.laneRefs) {
359	    const show = bySlug.get(ref.slug);
360	    if (!show) continue;
361	    const { catchable, count, reason } = laneVerdict(show.performances, filter);
362	    ref.el.classList.toggle("lane--out", !catchable);
363	    ref.statusEl.innerHTML = catchable
364	      ? `<span class="st-ok">&check; ${count} date${count === 1 ? "" : "s"}</span>`
365	      : `<span class="st-why">${escapeHtml(reason)}</span>`;
366	  }
367	}
368	
369	/** Per-show reason ladder mirroring the mock: sold out > not running > outside times. */
370	function laneVerdict(performances, filter) {
371	  const inRange = performances.filter((p) => p.date >= filter.dateStart && p.date <= filter.dateEnd);
372	  if (inRange.length === 0) {
373	    return { catchable: false, reason: "not running in this window" };
374	  }
375	  const availableInRange = inRange.filter((p) => p.available);
376	  if (availableInRange.length === 0) {
377	    return { catchable: false, reason: "sold out in this window" };
378	  }
379	  const inWindow = availableInRange.filter((p) => p.inWindow);
380	  if (inWindow.length > 0) {
381	    return { catchable: true, count: inWindow.length };
382	  }
383	  const times = [...new Set(availableInRange.map((p) => p.start))].sort();
384	  return { catchable: false, reason: `starts ${times[0]} — outside your times` };
385	}
386	
387	function updateHero(counts, filter) {
388	  const hcIn = $("hcIn");
389	  const changed = hcIn.textContent !== String(counts.showsAvailableInWindow);
390	  hcIn.textContent = counts.showsAvailableInWindow;
391	  $("hcAll").textContent = counts.matchedShows;
392	  $("hcDetail").textContent =
393	    `${state.d0}–${state.d1} Aug · starting ${fmtT(state.t0)}–${fmtT(state.t1)}`;
394	  if (changed) {
395	    const num = hcIn.closest(".hc-num");
396	    num.classList.remove("bump");
397	    void num.offsetWidth; // restart the CSS animation
398	    num.classList.add("bump");
399	  }
400	}
401	
402	/** rAF-throttled: re-summarize + re-render verdicts, coalesced to once per frame. */
403	let recomputeScheduled = false;
404	function scheduleRecompute() {
405	  if (recomputeScheduled) return;
406	  recomputeScheduled = true;
407	  requestAnimationFrame(() => {
408	    recomputeScheduled = false;
409	    recomputeAndRender();
410	  });
411	}
412	function recomputeAndRender() {
413	  const filter = currentFilter();
414	  const result = summarize(state.matched, filter, state.totalFavourites);
415	  const bySlug = new Map(result.shows.map((s) => [s.slug, s]));
416	  applyVerdicts(bySlug, filter);
417	  updateHero(result.counts, filter);
418	}
419	
420	// --- Window overlay geometry & date-window dragging ------------------------
421	
422	const calWrap = () => $("calWrap");
423	const calInner = () => $("calInner");
424	
425	function layoutOverlay() {
426	  const daysEl = $("dayHead");
427	  const dr = daysEl.getBoundingClientRect();
428	  if (dr.width === 0) return; // panel not visible yet
429	  const wr = calInner().getBoundingClientRect();
430	  const trackLeft = dr.left - wr.left;
431	  const trackWidth = dr.width;
432	  const dayW = trackWidth / DAYS_IN_MONTH;
433	  state.layout = { trackLeft, trackWidth, dayW };
434	
435	  const win = $("win");
436	  win.style.left = trackLeft + "px";
437	  win.style.width = trackWidth + "px";
438	
439	  const festEnd = $("festEnd");
440	  festEnd.style.left = trackLeft + FEST_END_DAY * dayW + "px";
441	  festEnd.style.width = (DAYS_IN_MONTH - FEST_END_DAY) * dayW + "px";
442	
443	  paintWindow();
444	}
445	
446	function paintWindow() {
447	  const { trackWidth, dayW } = state.layout;
448	  const x0 = (state.d0 - 1) * dayW;
449	  const x1 = state.d1 * dayW;
450	  $("dimL").style.left = "0";
451	  $("dimL").style.width = x0 + "px";
452	  $("dimR").style.left = x1 + "px";
453	  $("dimR").style.width = Math.max(0, trackWidth - x1) + "px";
454	  $("band").style.left = x0 + "px";
455	  $("band").style.width = (x1 - x0) + "px";
456	  $("hStart").style.left = x0 + "px";
457	  $("hEnd").style.left = x1 + "px";
458	  $("flagStart").textContent = `${state.d0} Aug`;
459	  $("flagEnd").textContent = `${state.d1} Aug`;
460	  const hStart = $("hStart");
461	  hStart.setAttribute("aria-valuenow", state.d0);
462	  hStart.setAttribute("aria-valuetext", `${state.d0} August`);
463	  const hEnd = $("hEnd");
464	  hEnd.setAttribute("aria-valuenow", state.d1);
465	  hEnd.setAttribute("aria-valuetext", `${state.d1} August`);
466	}
467	
468	function dayAt(clientX) {
469	  const wr = calInner().getBoundingClientRect();
470	  const { trackLeft, dayW } = state.layout;
471	  return clamp(Math.round((clientX - wr.left - trackLeft) / dayW), 0, DAYS_IN_MONTH);
472	}
473	
474	/** Wire pointer-drag on a date handle/band; `apply` mutates state.d0/d1 per move. */
475	function dragDate(el, apply) {
476	  el.addEventListener("pointerdown", (e) => {
477	    e.preventDefault();
478	    el.setPointerCapture(e.pointerId);
479	    const startX = e.clientX;
480	    const s0 = state.d0;
481	    const s1 = state.d1;
482	    const move = (ev) => {
483	      apply(ev, s0, s1, startX);
484	      paintWindow();
485	      scheduleRecompute();
486	    };
487	    const up = () => {
488	      el.removeEventListener("pointermove", move);
489	      el.removeEventListener("pointerup", up);
490	    };
491	    el.addEventListener("pointermove", move);
492	    el.addEventListener("pointerup", up);
493	  });
494	}
495	
496	function keysDate(el, fn) {
497	  el.addEventListener("keydown", (e) => {
498	    const dd = e.key === "ArrowLeft" ? -1 : e.key === "ArrowRight" ? 1 : 0;
499	    if (!dd) return;
500	    e.preventDefault();
501	    fn(dd);
502	    paintWindow();
503	    scheduleRecompute();
504	  });
505	}
506	
507	// --- Time-of-day dual slider ------------------------------------------------
508	
509	function paintTime() {
510	  const tsH = [$("tsH0"), $("tsH1")];
511	  const tsB = [$("tsB0"), $("tsB1")];
512	  const pct = (m) => ((m - T_MIN) / (T_MAX - T_MIN)) * 100;
513	  tsH[0].style.left = pct(state.t0) + "%";
514	  tsH[1].style.left = pct(state.t1) + "%";
515	  $("tsFill").style.left = pct(state.t0) + "%";
516	  $("tsFill").style.width = (pct(state.t1) - pct(state.t0)) + "%";
517	  tsB[0].textContent = fmtT(state.t0);
518	  tsB[1].textContent = fmtT(state.t1);
519	  $("todFrom").textContent = fmtT(state.t0);
520	  $("todTo").textContent = fmtT(state.t1);
521	  tsH[0].setAttribute("aria-valuenow", state.t0);
522	  tsH[0].setAttribute("aria-valuetext", fmtT(state.t0));
523	  tsH[1].setAttribute("aria-valuenow", state.t1);
524	  tsH[1].setAttribute("aria-valuetext", fmtT(state.t1));
525	}
526	
527	function timeAt(clientX) {
528	  const r = $("tslider").getBoundingClientRect();
529	  const raw = T_MIN + ((clientX - r.left) / r.width) * (T_MAX - T_MIN);
530	  return clamp(Math.round(raw / T_STEP) * T_STEP, T_MIN, T_MAX);
531	}
532	
533	function dragTime(index) {
534	  const el = index === 0 ? $("tsH0") : $("tsH1");
535	  el.addEventListener("pointerdown", (e) => {
536	    e.preventDefault();
537	    el.setPointerCapture(e.pointerId);
538	    const move = (ev) => {
539	      if (index === 0) state.t0 = clamp(timeAt(ev.clientX), T_MIN, state.t1 - T_GAP);
540	      else state.t1 = clamp(timeAt(ev.clientX), state.t0 + T_GAP, T_MAX);
541	      paintTime();
542	      scheduleRecompute();
543	    };
544	    const up = () => {
545	      el.removeEventListener("pointermove", move);
546	      el.removeEventListener("pointerup", up);
547	    };
548	    el.addEventListener("pointermove", move);
549	    el.addEventListener("pointerup", up);
550	  });
551	  el.addEventListener("keydown", (e) => {
552	    const dd = e.key === "ArrowLeft" ? -T_STEP : e.key === "ArrowRight" ? T_STEP : 0;
553	    if (!dd) return;
554	    e.preventDefault();
555	    if (index === 0) state.t0 = clamp(state.t0 + dd, T_MIN, state.t1 - T_GAP);
556	    else state.t1 = clamp(state.t1 + dd, state.t0 + T_GAP, T_MAX);
557	    paintTime();
558	    scheduleRecompute();
559	  });
560	}
561	
562	// --- Wiring -----------------------------------------------------------
563	
564	function wireDropzone() {
565	  const dz = $("dropzone");
566	  const input = $("csvInput");
567	
568	  input.addEventListener("change", () => {
569	    if (input.files && input.files[0]) handleFile(input.files[0]);
570	    input.value = ""; // allow re-selecting the same filename later
571	  });
572	
573	  ["dragenter", "dragover"].forEach((evt) =>
574	    dz.addEventListener(evt, (e) => {
575	      e.preventDefault();
576	      dz.classList.add("is-dragover");
577	    })
578	  );
579	  ["dragleave", "dragend"].forEach((evt) =>
580	    dz.addEventListener(evt, () => dz.classList.remove("is-dragover"))
581	  );
582	  dz.addEventListener("drop", (e) => {
583	    e.preventDefault();
584	    dz.classList.remove("is-dragover");
585	    const file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
586	    if (file) handleFile(file);
587	  });
588	}
589	
590	function wireSampleLink() {
591	  $("sampleLink").addEventListener("click", async (e) => {
592	    e.preventDefault();
593	    try {
594	      const res = await fetch(SAMPLE_URL);
595	      if (!res.ok) throw new Error(`HTTP ${res.status}`);
596	      const text = await res.text();
597	      processFavouritesText(text, "sample-favourites.csv");
598	    } catch (err) {
599	      console.error("Fringe Planner: failed to load sample favourites", err);
600	      alert("Couldn't load the sample favourites — please try uploading a file instead.");
601	    }
602	  });
603	}
604	
605	function wireContinueButton() {
606	  $("continueBtn").addEventListener("click", () => {
607	    if (state.matched.length > 0) revealCalendar();
608	  });
609	}
610	
611	function wireRetry() {
612	  $("retryBtn").addEventListener("click", loadData);
613	}
614	
615	function wireCalendarControls() {
616	  dragDate($("hStart"), (ev) => {
617	    state.d0 = clamp(dayAt(ev.clientX) + 1, 1, state.d1);
618	  });
619	  dragDate($("hEnd"), (ev) => {
620	    state.d1 = clamp(dayAt(ev.clientX), state.d0, DAYS_IN_MONTH);
621	  });
622	  dragDate($("band"), (ev, s0, s1, startX) => {
623	    const { dayW } = state.layout;
624	    const dd = Math.round((ev.clientX - startX) / dayW);
625	    const len = s1 - s0;
626	    state.d0 = clamp(s0 + dd, 1, DAYS_IN_MONTH - len);
627	    state.d1 = state.d0 + len;
628	  });
629	  keysDate($("hStart"), (dd) => {
630	    state.d0 = clamp(state.d0 + dd, 1, state.d1);
631	  });
632	  keysDate($("hEnd"), (dd) => {
633	    state.d1 = clamp(state.d1 + dd, state.d0, DAYS_IN_MONTH);
634	  });
635	
636	  dragTime(0);
637	  dragTime(1);
638	
639	  window.addEventListener("resize", () => layoutOverlay());
640	}
641	
642	// --- Go ---------------------------------------------------------------
643	
644	wireDropzone();
645	wireSampleLink();
646	wireContinueButton();
647	wireRetry();
648	wireCalendarControls();
649	paintTime();
650	loadData();
651

