1	// Main API the UI calls: matching favourites against the show catalogue,
2	// summarizing availability within a date/time window, and (for later use) the
3	// scheduling primitives ported from edfringe/scheduling.py.
4	//
5	// Pure — no DOM, no fetch. The UI is responsible for loading data/normalized/
6	// shows.json and the favourites file text and passing them in.
7	
8	import { urlFromSlug } from "./favourites.js";
9	import {
10	  isAvailable,
11	  isNonTicketed,
12	  dateTimeToMinutes,
13	  timeToMinutesOfDay,
14	} from "./availability.js";
15	
16	// --- indexing / matching --------------------------------------------------
17	
18	/**
19	 * Index shows by slug for O(1) favourite lookup.
20	 * @param {object[]} shows shows.json array
21	 * @returns {Map<string, object>}
22	 */
23	export function buildIndex(shows) {
24	  const index = new Map();
25	  for (const show of shows || []) {
26	    if (show && show.slug) index.set(show.slug, show);
27	  }
28	  return index;
29	}
30	
31	/**
32	 * Resolve favourite slugs against the show index.
33	 * @param {string[]} slugs de-duplicated slugs from parseFavourites
34	 * @param {Map<string, object>} index from buildIndex
35	 * @returns {{matched: object[], missingSlugs: string[]}}
36	 */
37	export function matchFavourites(slugs, index) {
38	  const matched = [];
39	  const missingSlugs = [];
40	  for (const slug of slugs || []) {
41	    const show = index.get(slug);
42	    if (show) matched.push(show);
43	    else missingSlugs.push(slug);
44	  }
45	  return { matched, missingSlugs };
46	}
47	
48	// --- summarizing availability within a window -----------------------------
49	
50	/**
51	 * Normalize a startTimeMin/Max filter bound to minutes-since-midnight: pass
52	 * through a number as-is, or parse an "HH:MM" string.
53	 * @param {number|string} bound
54	 * @returns {number}
55	 */
56	function normalizeTimeBound(bound) {
57	  if (typeof bound === "number") return bound;
58	  if (typeof bound === "string") return timeToMinutesOfDay(bound);
59	  throw new TypeError(`Expected number or "HH:MM" string, got ${JSON.stringify(bound)}`);
60	}
61	
62	/**
63	 * Annotate every performance of every show against a date/time-of-day window,
64	 * and roll up summary counts.
65	 *
66	 * @param {object[]} shows shows to summarize (typically matchFavourites(...).matched)
67	 * @param {{dateStart: string, dateEnd: string, startTimeMin: number|string, startTimeMax: number|string}} filter
68	 *   dateStart/dateEnd are "YYYY-MM-DD" (inclusive). startTimeMin/startTimeMax are
69	 *   either minutes-since-midnight or "HH:MM" strings (inclusive).
70	 * @param {number} [totalFavourites] total favourite slugs before matching (defaults
71	 *   to shows.length when the caller only has the matched set on hand).
72	 * @returns {{
73	 *   counts: {totalFavourites: number, matchedShows: number, showsAvailableInWindow: number},
74	 *   shows: Array<{
75	 *     slug: string, title: string,
76	 *     performances: Array<{date: string, start: string, available: boolean, status: string|null, soldOut: boolean, inWindow: boolean}>,
77	 *     availableDateSpan: {min: string, max: string} | null,
78	 *   }>,
79	 * }}
80	 */
81	export function summarize(shows, filter, totalFavourites) {
82	  const dateStart = filter.dateStart;
83	  const dateEnd = filter.dateEnd;
84	  const startTimeMin = normalizeTimeBound(filter.startTimeMin);
85	  const startTimeMax = normalizeTimeBound(filter.startTimeMax);
86	
87	  const summarizedShows = (shows || []).map((show) => {
88	    let availableMin = null;
89	    let availableMax = null;
90	    let hasInWindow = false;
91	
92	    const performances = (show.performances || []).map((perf) => {
93	      const available = isAvailable(perf);
94	      if (available) {
95	        if (availableMin === null || perf.date < availableMin) availableMin = perf.date;
96	        if (availableMax === null || perf.date > availableMax) availableMax = perf.date;
97	      }
98	      const dateInRange = perf.date >= dateStart && perf.date <= dateEnd;
99	      const startMinOfDay = timeToMinutesOfDay(perf.start);
100	      const timeInRange = startMinOfDay >= startTimeMin && startMinOfDay <= startTimeMax;
101	      const inWindow = available && dateInRange && timeInRange;
102	      if (inWindow) hasInWindow = true;
103	      return {
104	        date: perf.date,
105	        start: perf.start,
106	        available,
107	        status: perf.status ?? null,
108	        soldOut: !!perf.soldOut,
109	        inWindow,
110	      };
111	    });
112	
113	    return {
114	      slug: show.slug,
115	      title: show.title,
116	      performances,
117	      availableDateSpan: availableMin ? { min: availableMin, max: availableMax } : null,
118	      _hasInWindow: hasInWindow, // internal, stripped before returning below
119	    };
120	  });
121	
122	  const showsAvailableInWindow = summarizedShows.filter((s) => s._hasInWindow).length;
123	  for (const s of summarizedShows) delete s._hasInWindow;
124	
125	  return {
126	    counts: {
127	      totalFavourites: totalFavourites ?? (shows ? shows.length : 0),
128	      matchedShows: shows ? shows.length : 0,
129	      showsAvailableInWindow,
130	    },
131	    shows: summarizedShows,
132	  };
133	}
134	
135	// --- scheduling primitives (for later use) ---------------------------------
136	// Ported from edfringe/scheduling.py. Default trip window and gap match the
137	// Python module's defaults for 2026; all are overridable parameters here
138	// rather than module-level globals (Python's `configure()`).
139	
140	export const DEFAULT_WINDOW_START = "2026-08-07T15:00";
141	export const DEFAULT_WINDOW_END = "2026-08-24T17:00";
142	export const DEFAULT_MIN_GAP_SAME_VENUE = 0;
143	export const DEFAULT_MIN_GAP_DIFFERENT_VENUE = 30;
144	
145	/**
146	 * Parse a "YYYY-MM-DDTHH:MM" (or Date) into minutes-since-epoch, consistent
147	 * with availability.js's wall-clock minute counting.
148	 * @param {string|Date} value
149	 * @returns {number}
150	 */
151	function toMinutes(value) {
152	  if (value instanceof Date) return value.getTime() / 60000;
153	  const [date, time] = value.split("T");
154	  return dateTimeToMinutes(date, time || "00:00");
155	}
156	
157	/**
158	 * One bookable performance of a show, eligible for scheduling. Mirrors
159	 * scheduling.py's Slot dataclass, adapted to shows.json's fields (venueCode
160	 * from `show.venue`, no separate various-venue flag in this dataset).
161	 * @typedef {object} Slot
162	 * @property {string} slug
163	 * @property {string} title
164	 * @property {string|null} genre
165	 * @property {string} date
166	 * @property {string} startTime "HH:MM"
167	 * @property {number} start minutes since epoch
168	 * @property {number} end minutes since epoch
169	 * @property {string|null} venueCode
170	 * @property {string|null} venueName
171	 * @property {string|null} room
172	 * @property {string} url
173	 * @property {boolean} freeNonTicketed
174	 */
175	
176	/**
177	 * Per-show available performances that fit entirely inside the trip window.
178	 * Mirrors scheduling.py's `eligible_slots` (window + availability filter only
179	 * — gap/overlap compatibility is a separate concern, see `compatible`).
180	 *
181	 * @param {object[]} shows
182	 * @param {{windowStart?: string|Date, windowEnd?: string|Date, minGap?: number}} [options]
183	 *   minGap is accepted for API symmetry with the gap-aware helpers below but is
184	 *   not applied here (Python's eligible_slots doesn't gap-filter either — that
185	 *   happens when building a schedule from the slots).
186	 * @returns {Map<string, Slot[]>}
187	 */
188	export function eligibleSlots(shows, options = {}) {
189	  const windowStart = toMinutes(options.windowStart ?? DEFAULT_WINDOW_START);
190	  const windowEnd = toMinutes(options.windowEnd ?? DEFAULT_WINDOW_END);
191	
192	  const out = new Map();
193	  for (const show of shows || []) {
194	    const slots = [];
195	    for (const perf of show.performances || []) {
196	      if (!isAvailable(perf)) continue;
197	      const start = dateTimeToMinutes(perf.date, perf.start);
198	      const end = show.duration ? start + show.duration : start;
199	      if (start < windowStart || end > windowEnd) continue;
200	      slots.push({
201	        slug: show.slug,
202	        title: show.title,
203	        genre: show.genre ?? null,
204	        date: perf.date,
205	        startTime: perf.start,
206	        start,
207	        end,
208	        venueCode: show.venue ?? null,
209	        venueName: show.venueName ?? null,
210	        room: show.room ?? null,
211	        url: urlFromSlug(show.slug),
212	        freeNonTicketed: isNonTicketed(perf),
213	      });
214	    }
215	    slots.sort((a, b) => a.start - b.start || a.end - b.end);
216	    out.set(show.slug, slots);
217	  }
218	  return out;
219	}
220	
221	/**
222	 * Minutes required between two slots: the same-venue buffer when both share a
223	 * known venue code, otherwise the different-venue buffer. Mirrors
