cd /tmp/claude-0/-home-user/03f08fe7-defa-5cbc-ad08-8623364a3d12/scratchpad && cat > verify.mjs <<'EOF'
const TTL_MS = 3 * 24 * 60 * 60 * 1000;
// --- stub localStorage ---
let store = {};
const localStorage = {
  getItem: (k) => (k in store ? store[k] : null),
  setItem: (k, v) => { store[k] = String(v); },
  removeItem: (k) => { delete store[k]; },
};
const STORAGE_KEY = "edfringe.plan.favourites.v1";
function clearStoredFavourites(){ try{localStorage.removeItem(STORAGE_KEY);}catch{} }
function saveFavourites(slugs, filename, savedAt){ localStorage.setItem(STORAGE_KEY, JSON.stringify({v:1,slugs,filename,savedAt})); }
function loadStoredFavourites(){
  let raw=null; try{raw=localStorage.getItem(STORAGE_KEY);}catch{return null;}
  if(!raw) return null;
  let data; try{data=JSON.parse(raw);}catch{clearStoredFavourites();return null;}
  if(!data||!Array.isArray(data.slugs)||typeof data.savedAt!=="number"){clearStoredFavourites();return null;}
  if(Date.now()-data.savedAt>TTL_MS){clearStoredFavourites();return null;}
  return {slugs:data.slugs.filter(s=>typeof s==="string"),filename:typeof data.filename==="string"?data.filename:"",savedAt:data.savedAt};
}
function dayDiff(a,b){const da=Date.UTC(a.getFullYear(),a.getMonth(),a.getDate());const db=Date.UTC(b.getFullYear(),b.getMonth(),b.getDate());return Math.round((db-da)/86400000);}
function fmtSavedWhen(ts){if(!ts)return "this session";const then=new Date(ts);const days=dayDiff(then,new Date());if(days<=0)return "today";if(days===1)return "yesterday";return then.toLocaleDateString("en-GB",{day:"numeric",month:"short"});}

const assert=(c,m)=>{if(!c)throw new Error("FAIL: "+m);console.log("ok - "+m);};
const now=Date.now();
// fresh save/load round-trip
saveFavourites(["a-show","b-show"],"fav.csv",now);
let r=loadStoredFavourites();
assert(r&&r.slugs.length===2&&r.filename==="fav.csv","round-trips saved favourites");
// expired (>3 days) is dropped and removed
saveFavourites(["x"],"old.csv",now-(TTL_MS+1000));
assert(loadStoredFavourites()===null,"expired record returns null");
assert(localStorage.getItem(STORAGE_KEY)===null,"expired record is purged from storage");
// just-inside TTL survives
saveFavourites(["x"],"c.csv",now-(TTL_MS-60000));
assert(loadStoredFavourites()!==null,"record just inside TTL survives");
// corrupt JSON purged
store[STORAGE_KEY]="{not json";
assert(loadStoredFavourites()===null,"corrupt JSON returns null");
assert(localStorage.getItem(STORAGE_KEY)===null,"corrupt JSON purged");
// wrong shape purged
store[STORAGE_KEY]=JSON.stringify({v:1,slugs:"nope",savedAt:now});
assert(loadStoredFavourites()===null,"bad shape returns null");
// non-string slugs filtered out
saveFavourites(["good",42,null,"also-good"],"m.csv",now);
assert(loadStoredFavourites().slugs.join(",")==="good,also-good","filters non-string slugs");
// date labels
assert(fmtSavedWhen(now)==="today","today label");
assert(fmtSavedWhen(now-24*3600*1000-3600*1000)==="yesterday","yesterday label");
assert(/\d+ \w+/.test(fmtSavedWhen(now-2*24*3600*1000-3600*1000)),"older uses DD Mon");
assert(fmtSavedWhen(null)==="this session","null savedAt fallback");
console.log("\nALL PASSED");
EOF
